# -*- coding: utf-8 -*-
# koja1 Kore: ek kronoloji_cok maddeleri (Balhae, Baekje restorasyonu)
from _kr_cok import *

cok('0762-01-01', "Tang Balhae'yi 'krallık' olarak tanıdı; Dae Hum-mu 'Balhae Kralı' ve Genel Vali unvanı aldı", 'siyaset', ['balhae', 'tang'],
    "Baoying 1. yılda Tang imparatoru Balhae komutanlığını krallığa yükseltti ve Dae Hum-mu'yu kral tanıyıp 'kıdemli yardımcı büyük general' unvanını verdi; Balhae başkenti bu sırada (755 sonrası) Sanggyeong'a taşınmıştı.",
    [(XT219, '寶應元年，詔以渤海爲國，欽茂王之，進檢校太尉。')], 'Baoying 1 (762)', 'yil', "Gün yok: yıl.", 'Sanggyeong (Longquanfu)')
cok('0830-01-01', "Balhae Kralı Dae Inseon öldü; torunu Dae Ijin tahta çıktı (Balhae'nin 'Doğu'nun Gelişmiş Ülkesi' dönemi)", 'hukumdar', ['balhae'],
    "Dahe 4. yılda Dae Inseon (Seon-wang) öldü; oğlu Sindeok erken öldüğünden torunu Yijin (Dae Ijin) tahta çıktı, ertesi yıl Tang'dan unvanı aldı. Kaynak Balhae'nin beş başkent, on beş eyalet, altmış iki vilayetle 'Doğu'nun gelişmiş ülkesi' olduğunu aynı bölümde kaydeder.",
    [(XT219, '大和四年，仁秀死，諡宣王。', '改年鹹和。'), (XT219, '地有五京、十五府、六十二州。')], 'Dahe 4 (830)', 'yil',
    "Gün yok: yıl. Dae Inseon'un saltanat başlangıcı Xin Tangshu'da yıl olarak verilmez (元和 806-820 aralığında): yazılmadı.", '')
cok('0663-01-01', "Baekgang (Hakusukinoe) Savaşı: Tang-Silla donanması Yamato-Baekje filosunu yaktı; Churyu-seong düştü", 'savas', ['tang', 'baekje-restorasyon', 'silla'],
    "Tang generali Sun Renshi, Liu Renyuan ve Liu Renguei Silla kralıyla birlikte Churyu-seong'u kuşatırken Liu Renguei donanmasıyla Baek nehrinde Yamato filosuyla karşılaştı ve dört çarpışmayı kazanıp dört yüz gemiyi yaktı; Baekje kralı Pung Goguryeo'ya kaçtı.",
    [(Z201, '遇倭兵於白江口，四戰皆捷，焚其舟四百艘，煙炎灼天，海水皆赤。', '百濟王豐脫身奔高麗')], 'Longshuo 3 (663)', 'yil',
    "ÇELİŞKİ (tarih): Zizhi tongjian j.201 olayı «九月，戊午» altında verir; Nihon Shoki 8. ay 27-28 (戊申) verir (mevcut 0663-10-04 maddesi, yamato). Ay-güneş takvim farkı (Tang/Silla ve Yamato takvimleri) nedeniyle gün seçilmedi: yıl hassasiyeti. Künye t 0663-01-01 ile çelişir: olay 663 yılının sonbaharındadır, yani künye t'si yıl başı olamaz (RAPOR).", 'Churyu-seong', 4, 2, '', 'konu-askeri')
